// AcceptanceSessionTitleLifecycleTests.swift の既存ヘルパーを使用する追加テスト案（未実行）
@Test @MainActor
func 別セッションの同一項目IDで保存由来が変わらない() async throws {
    let itemID = UUID().uuidString
    let mediaType = "application/x-phlox-session-title-origin"
    let storeA = TitleLifecycleTranscriptStore([
        .userMessage(id: itemID, text: "/review\n補足指示", timestamp: Date(),
                     attachments: [ChatUserAttachment(filename: "/review", mediaType: mediaType)])
    ])
    let storeB = TitleLifecycleTranscriptStore([
        .userMessage(id: itemID, text: "別セッションの本文", timestamp: Date(),
                     attachments: [ChatUserAttachment(filename: "別セッションの本文", mediaType: mediaType)])
    ])
    let (a, _) = makeChatVM(transcriptStore: storeA)
    await a.restore(threadId: "a", approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
    #expect(a.titleState.source == .flower)
    let (b, _) = makeChatVM(transcriptStore: storeB)
    await b.restore(threadId: "b", approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
    await a.flushTranscriptNow()
    let (restoredA, _) = makeChatVM(transcriptStore: storeA)
    await restoredA.restore(threadId: "a", approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
    #expect(restoredA.titleState == .generated(flowerName: "Rose"))
    await a.terminate()
    await b.terminate()
    await restoredA.terminate()
}

// AcceptanceSessionTitleLifecycleTests.swift の既存ヘルパーを使用する追加テスト案（未実行）
@Test @MainActor
func 履歴由来の補足本文を再起動後に採用しない() async throws {
    // 実 ClaudeSessionTranscriptLoader が isMeta:true の user 行から返す形。
    let imported: [ChatItem] = [
        .userMessage(id: UUID().uuidString, text: "補足指示", timestamp: Date())
    ]
    let entry = ClaudeSessionHistoryEntry(
        sessionID: "history-meta", preview: "", firstUserAt: nil,
        lastModified: Date(), gitBranch: nil,
        fileURL: URL(fileURLWithPath: "/tmp/history-meta.jsonl")
    )
    let store = TitleLifecycleTranscriptStore()
    let (first, _) = makeChatVM(
        transcriptStore: store, historyTranscriptLoader: { _ in imported }
    )
    await first.startFromHistory(entry)
    #expect(first.titleState.source == .flower)
    await first.flushTranscriptNow()
    await first.terminate()
    let (restored, _) = makeChatVM(transcriptStore: store)
    await restored.restore(threadId: entry.sessionID,
                           approvalPolicy: .named("on-request"),
                           sandbox: .named("workspace-write"))
    #expect(restored.titleState == .generated(flowerName: "Rose"))
    await restored.terminate()
}
